/**
 * The API route catalogue — every `METHOD /path` the dispatcher (`src/core/routes.ts`) can answer,
 * as data. Generated from the dispatcher's `case` table (the same source `tools/api-doc.mjs` reads);
 * do not edit by hand. Regenerate after adding or renaming an endpoint:
 *
 *   grep -oE "case '(GET|POST) [^']+'" src/core/routes.ts  (see tools/api-doc.mjs for the pattern)
 *
 * Its consumer is the request guard (`src/core/requestguard.ts`): the Bloom filter is seeded from
 * this list, so a path that is definitely not here is refused before authentication work, body
 * parsing or a dispatcher/database round-trip. `requestguard.test.ts` re-derives this list from
 * `routes.ts` and fails if the two drift — the catalogue can never quietly go stale.
 */

